#!/usr/bin/env node
// Generate portal/attack-catalog.js from MITRE's official ATT&CK Enterprise
// STIX bundle (https://github.com/mitre-attack/attack-stix-data).
//
// The portal needs tactic order, technique/sub-technique names and each
// technique's real tactic membership — nothing else — so the 50+ MB bundle
// is reduced to a small, pinned, deterministic script. Re-run this to move
// the course to a newer ATT&CK release; commit the regenerated file.
//
//   node bin/build-attack-catalog.js                 fetch the pinned version
//   node bin/build-attack-catalog.js 19.2            fetch a specific version
//   node bin/build-attack-catalog.js ./bundle.json   use a local bundle
const fs = require('fs'), path = require('path');

const DEFAULT_VERSION = '19.2';
const OUT = path.join(__dirname, '..', 'portal', 'attack-catalog.js');

async function loadBundle(arg) {
  if (arg && fs.existsSync(arg)) return JSON.parse(fs.readFileSync(arg, 'utf8'));
  const version = arg || DEFAULT_VERSION;
  const url = `https://raw.githubusercontent.com/mitre-attack/attack-stix-data/master/enterprise-attack/enterprise-attack-${version}.json`;
  const response = await fetch(url);
  if (!response.ok) throw new Error(`Fetch failed (${response.status}) for ${url}`);
  return response.json();
}

const attackId = (object) => object.external_references?.find((ref) => ref.source_name === 'mitre-attack')?.external_id;

(async () => {
  const bundle = await loadBundle(process.argv[2]);
  const objects = bundle.objects;
  const byStixId = new Map(objects.map((object) => [object.id, object]));
  const collection = objects.find((object) => object.type === 'x-mitre-collection');
  const matrix = objects.find((object) => object.type === 'x-mitre-matrix');
  if (!collection || !matrix) throw new Error('Not an ATT&CK Enterprise bundle: collection or matrix object missing.');

  // Tactic order is the matrix's own column order, as on attack.mitre.org.
  const tactics = matrix.tactic_refs.map((ref) => byStixId.get(ref)).map((tactic) => [attackId(tactic), tactic.name, tactic.x_mitre_shortname]);
  const tacticByShortname = new Map(tactics.map(([id, , shortname]) => [shortname, id]));

  const techniques = objects
    .filter((object) => object.type === 'attack-pattern' && !object.revoked && !object.x_mitre_deprecated)
    .map((object) => {
      const tacticIds = (object.kill_chain_phases || [])
        .filter((phase) => phase.kill_chain_name === 'mitre-attack')
        .map((phase) => tacticByShortname.get(phase.phase_name))
        .filter(Boolean)
        .sort((a, b) => tactics.findIndex(([id]) => id === a) - tactics.findIndex(([id]) => id === b));
      return [attackId(object), object.name, tacticIds.join(' ')];
    })
    .filter(([id, , tacticIds]) => id && tacticIds)
    .sort(([a], [b]) => a.localeCompare(b, 'en', { numeric: true }));

  const version = collection.x_mitre_version;
  // The exact notice MITRE's terms of use require on reproductions.
  const notice = `© ${String(collection.modified).slice(0, 4)} The MITRE Corporation. This work is reproduced and distributed with the permission of The MITRE Corporation.`;
  const rows = (list) => list.map((row) => `    ${JSON.stringify(row)},`).join('\n');
  const source = `/* GENERATED by bin/build-attack-catalog.js — do not edit by hand.
 *
 * MITRE ATT&CK® Enterprise v${version} (${String(collection.modified).slice(0, 10)}): tactics in matrix
 * order and every active technique and sub-technique with its tactics.
 * ${notice}
 * Terms of use: https://attack.mitre.org/resources/legal-and-branding/terms-of-use/
 */
const MnAttackCatalog = (() => {
  'use strict';
  const VERSION = ${JSON.stringify(version)};
  const NOTICE = ${JSON.stringify(notice)};
  // [id, name, shortname]
  const TACTIC_ROWS = [
${rows(tactics)}
  ];
  // [id, name, space-separated tactic ids]
  const TECHNIQUE_ROWS = [
${rows(techniques)}
  ];

  const tactics = Object.freeze(TACTIC_ROWS.map(([id, name, shortname]) => Object.freeze({ id, name, shortname })));
  const tacticById = new Map(tactics.map((tactic) => [tactic.id, tactic]));
  const techniqueById = new Map();
  TECHNIQUE_ROWS.forEach(([id, name, tacticIds]) => {
    const parent = id.includes('.') ? id.split('.')[0] : null;
    techniqueById.set(id, { id, name, parent, tactics: tacticIds.split(' '), subs: [] });
  });
  techniqueById.forEach((technique) => {
    const parent = technique.parent && techniqueById.get(technique.parent);
    if (parent) parent.subs.push(technique.id);
    technique.fullName = parent ? \`\${parent.name}: \${technique.name}\` : technique.name;
  });
  techniqueById.forEach((technique) => Object.freeze(Object.freeze(technique.tactics) && Object.freeze(technique.subs) && technique));

  const byName = (a, b) => techniqueById.get(a).name.localeCompare(techniqueById.get(b).name);
  const columns = new Map(tactics.map((tactic) => [tactic.id,
    [...techniqueById.values()].filter((t) => !t.parent && t.tactics.includes(tactic.id)).map((t) => t.id).sort(byName)]));

  return Object.freeze({
    VERSION,
    NOTICE,
    tactics,
    tactic: (id) => tacticById.get(id) || null,
    technique: (id) => techniqueById.get(id) || null,
    techniqueIds: () => [...techniqueById.keys()],
    // Parent techniques in one tactic column, alphabetical as on attack.mitre.org.
    column: (tacticId) => columns.get(tacticId) || [],
    // A sub-technique appears in a column only where it carries that tactic.
    subsIn: (techniqueId, tacticId) => (techniqueById.get(techniqueId)?.subs || []).filter((id) => techniqueById.get(id).tactics.includes(tacticId)).sort(byName),
    url: (id) => \`https://attack.mitre.org/\${/^TA/.test(id) ? 'tactics' : 'techniques'}/\${String(id).replace('.', '/')}/\`,
  });
})();
if (typeof module !== 'undefined') module.exports = MnAttackCatalog;
`;
  fs.writeFileSync(OUT, source);
  console.log(`Wrote ${path.relative(process.cwd(), OUT)}: ATT&CK v${version}, ${tactics.length} tactics, ${techniques.length} techniques (${(source.length / 1024).toFixed(0)} KB).`);
})().catch((error) => { console.error(error.message); process.exit(1); });
